use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub bid_key: String,
    pub solar_arrays: i64,
    pub wind_turbines: i64,
    pub storage_banks: i64,
    pub interconnects: i64,
    pub emergency_mode: bool,
    pub duplicate_bid: bool,
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub bid_key: String,
    pub generation_units: i64,
    pub battery_buffer_units: i64,
    pub grid_required_units: i64,
    pub grid_capacity_units: i64,
    pub delivered_units: i64,
    pub shortfall_units: i64,
    pub dispatch_windows: i64,
    pub bid_score: i64,
    pub bid_state: String,
}

pub fn score(solar: i64, wind: i64, storage: i64, interconnects: i64, emergency: bool) -> i64 {
    let generation = solar * 9 + wind * 13;
    let buffer = storage * if emergency { 7 } else { 3 };
    let required = generation + buffer;
    let capacity = interconnects * 55;
    let delivered = required.min(capacity);
    let shortfall = (required - capacity).max(0);
    let dispatch_windows = required.div_euclid(31);

    delivered + shortfall * 4 + dispatch_windows * 9
}

pub fn calculate(v: &RequestInput) -> ResponseOutput {
    let generation = v.solar_arrays * 9 + v.wind_turbines * 13;
    let buffer = v.storage_banks * if v.emergency_mode { 7 } else { 3 };
    let required = generation + buffer;
    let capacity = v.interconnects * 55;
    let delivered = required.min(capacity);
    let shortfall = (required - capacity).max(0);
    let dispatch_windows = required.div_euclid(31);
    let bid_score = delivered + shortfall * 4 + dispatch_windows * 9;
    let bid_state = if shortfall == 0 {
        "accepted"
    } else if v.emergency_mode {
        "emergency_shortfall"
    } else {
        "routine_shortfall"
    };

    ResponseOutput {
        bid_key: v.bid_key.clone(),
        generation_units: generation,
        battery_buffer_units: buffer,
        grid_required_units: required,
        grid_capacity_units: capacity,
        delivered_units: delivered,
        shortfall_units: shortfall,
        dispatch_windows,
        bid_score,
        bid_state: bid_state.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_browser_score(
    solar: i64,
    wind: i64,
    storage: i64,
    interconnects: i64,
    emergency: i32,
) -> i64 {
    score(solar, wind, storage, interconnects, emergency != 0)
}

